#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maxPointsActivated(std::vector<std::vector<int>>& grid) {
        int n = grid.size();
        std::vector<std::vector<int>> compId(n, std::vector<int>(n, 0));
        std::unordered_map<int, int> compSize;
        int cid = 1;

        auto dfs = [&](auto& self, int r, int c, int curId) -> int {
            compId[r][c] = curId;
            int sz = 1;
            int dr[] = {1, -1, 0, 0};
            int dc[] = {0, 0, 1, -1};
            for (int i = 0; i < 4; ++i) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1 && compId[nr][nc] == 0) {
                    sz += self(self, nr, nc, curId);
                }
            }
            return sz;
        };

        int maxComp = 0;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1 && compId[r][c] == 0) {
                    int sz = dfs(dfs, r, c, cid);
                    compSize[cid] = sz;
                    maxComp = std::max(maxComp, sz);
                    cid++;
                }
            }
        }

        int ans = maxComp;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 0) {
                    std::unordered_set<int> seen;
                    int cur = 1;
                    int dr[] = {1, -1, 0, 0};
                    int dc[] = {0, 0, 1, -1};
                    for (int i = 0; i < 4; ++i) {
                        int nr = r + dr[i], nc = c + dc[i];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && compId[nr][nc] > 0) {
                            int adj = compId[nr][nc];
                            if (seen.insert(adj).second) {
                                cur += compSize[adj];
                            }
                        }
                    }
                    ans = std::max(ans, cur);
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private int n;
    private int[][] grid;
    private int[][] compId;

    private int dfs(int r, int c, int curId) {
        compId[r][c] = curId;
        int sz = 1;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1 && compId[nr][nc] == 0) {
                sz += dfs(nr, nc, curId);
            }
        }
        return sz;
    }

    public int maxPointsActivated(int[][] grid) {
        this.grid = grid;
        this.n = grid.length;
        this.compId = new int[n][n];
        Map<Integer, Integer> compSize = new HashMap<>();
        int cid = 1;
        int maxComp = 0;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1 && compId[r][c] == 0) {
                    int sz = dfs(r, c, cid);
                    compSize.put(cid, sz);
                    maxComp = Math.max(maxComp, sz);
                    cid++;
                }
            }
        }

        int ans = maxComp;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    Set<Integer> seen = new HashSet<>();
                    int cur = 1;
                    int[] dr = {1, -1, 0, 0};
                    int[] dc = {0, 0, 1, -1};
                    for (int i = 0; i < 4; i++) {
                        int nr = r + dr[i], nc = c + dc[i];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && compId[nr][nc] > 0) {
                            int adj = compId[nr][nc];
                            if (seen.add(adj)) {
                                cur += compSize.get(adj);
                            }
                        }
                    }
                    ans = Math.max(ans, cur);
                }
            }
        }
        return ans;
    }
}

